\label{antilinear operator adjoint}
	For $X\in \mathcal{B}_{a}(\mathcal{H})$, there is a unique $X^{\#}\in \mathcal{B}_{a}(\mathcal{H})$ called the anti-linear adjoint of $X$, if it satisfies the following relation
	\begin{equation}
		\langle Xx,y \rangle =\overline{\langle x, X^{\#}y \rangle}=\langle  X^{\#}y,x \rangle
	\end{equation}
	for all $x,y \in \mathcal{H}$.

\cite[Theorem 1]{Douglas Lemma}
	 If $A, B \in \mathcal{B}(\mathcal{H})$, then the following statements are equivalent:
	\begin{enumerate}
		\item[{\rm (i)}] $\text{ran}(A) \subseteq \text{ran}(B)$;
		\item[{\rm (ii)}] $A=BC$ for some $C \in \mathcal{B}(\mathcal{H})$;
		\item[{\rm (iii)}]$AA^* \leq k^2 BB^*$ for some $k\geq 0$.
	\end{enumerate}
	Moreover, if {\rm (i)}, {\rm (ii)}, and {\rm (iii)} are valid, then there exists a unique operator $C$ so that
	\begin{enumerate}
		\item[{\rm (a)}] $\|C\|^2=\inf\{\lambda|AA^*\leq \lambda BB^*\}$;
		\item[{\rm (b)}] $\ker(A) = \ker(C)$;
		\item[{\rm (c)}] $\text{ran}(C) \subseteq \overline{\text{ran}}(B^{*})$.
	\end{enumerate}

\cite[Lemma 3.3]{Gilbreath:Wogen}\label{anti-commut-normal}
		Suppose that $K$ is a conjugation and that the normal operator $N$ lies
		in $\mathcal{S}_{K}(\mathcal{H})$. Then $\{ A\in \mathcal{B}_{a}(\mathcal{H}):AN=NA \}=\{TK:T\in \mathcal{B}(\mathcal{H})\,\,\text{and}\,\, TN^*=NT  \}$.

\label{c-symmetric from c-normal}
		The following gives a way to construct $C$-symmetric operator and $C$-skew-symmetric operator given a $C$-normal operator.
		\begin{enumerate}
			\item If $T$ is $C$-normal, then $S_1=T^*T-TT^*$ is $C$-skew-symmetric.
			\item If $T$ is $C$-normal, then $S_2=T^*T+TT^*$ is $C$-symmetric.\\
		\end{enumerate}

\cite[Theorem 1.6]{Wang:Zhu}\label{cpolar}
	Let $C$ be a conjugation on $\mathcal{H}$ and $T \in \mathcal{B(H)}$. Then the following are
	equivalent:
	\begin{enumerate}
		\item $T$ is $C$-normal.
		\item $T = CJ|T|$ for some partial anti-unitary operator $J$ supported on $\text{ran}|T|$ with
		$J|T| = |T|J$.
		\item $T =C\tilde{J}|T| $ for some anti-unitary operator $\tilde{J}$ with $\tilde{J}|T|=|T|\tilde{J}$.
	\end{enumerate}

\cite[Proposition 4.3]{Wang:Zhu}\label{cnormaldirectsum}
	Let $\mathcal{M}$ be a subspace of $\mathcal{H}$ and $T\in \mathcal{B}(\mathcal{H})$ with 
	\begin{align}
	\begin{pmatrix}
	A&0\\
	0&B
	\end{pmatrix},
	\end{align}
	where $A:\mathcal{M}\rightarrow \mathcal{M}$ is a diagonal operator. Then $T\in (\mathcal{GS})$ if and only if $B:\mathcal{M}^{\perp}\rightarrow \mathcal{M}^{\perp}\in(\mathcal{GS})$.

\cite[Proposition 6.1]{Conway:Book:Functional analysis}\label{direct sum commut prop}
	The following are true:
	\begin{enumerate}
		\item If $A=\oplus_{n\geq 1} A_n$ is a bounded operator on $\mathcal{H}=\oplus_{n\geq 1} \mathcal{H}_n$ and $B=[B_{ij}]\in \mathcal{B}(\mathcal{H})$, then $AB=BA$ if and only if $B_{ij}A_j=A_iB_{ij}$ for all $i,j$.
		\item If $B=[B_{ij}]\in \mathcal{B}(\mathcal{H}^{(n)})$, then $BA^{(n)}=BA^{(n)}$ if and only if $B_{ij}A=AB_{ij}$ for all $i,j$, where $\mathcal{H}^{(n)}$ and $A^{(n)}$ are the direct sum of $n$ copies of $\mathcal{H}$ and $A$,respectively.
	\end{enumerate}

(\ref{AD1}) $\implies$(\ref{AD3})
	Let $C$ be a conjugation on $\mathcal{H}$. Set $A=T C$ and $B=S C$. Then $A$ and $B$ are linear operators. Since $C \mathcal{H}=\mathcal{H}$, we have

	\begin{equation*}
		\text{ran}(A)=\text{ran}(T C)=\text{ran}(T) \subseteq \text{ran}(S)=\text{ran}(S C)=\text{ran}(B).
	\end{equation*}

	Then by Douglas theorem, there is a $ D \in \mathcal{B}(\mathcal{H})$ such that

	$$
	\begin{aligned}
		& A=B D \\
		\Rightarrow T C & =S C D \\
		\Rightarrow T & =S C D C =S R, \text { where } R=C D C .
	\end{aligned}
	$$

	Note that $R\in \mathcal{B}(\mathcal{H})$.\\
	(\ref{AD3})$\implies$ (\ref{AD1})
	Using the fact that $C\mathcal{H}=\mathcal{H}$, we get $T\mathcal{H}=S R \mathcal{H} \subseteq S \mathcal{H} $ and this implies $ R(T) \subseteq R(S)$.\\
	(\ref{AD2}) $\implies$ (\ref{AD3}) Observe that $A A^{*}=T C C T^{\#}=T T^{\#}$ and $B B^{*}=S S^{\#}$. Therefore, $T T^{\#} \leq S S^{\#}$ implies $A A^{*} \leq B B^{*} $. By Douglas theorem, $ A=BD$ and hence $T=S R$.\\
	(\ref{AD3}) $\implies$ (\ref{AD2}) If $T=SR$, then
	\begin{equation*}
		\begin{split}
			S S^{\#}-T T^{\#}  &=S S^{\#}-S C D C C D^{*} C S^{\#} \\
			&=S S^{\#}-S C D D^{*} C S^{\#} 
			=S C\left(I-D D^{*}\right) C S^{\#} 
			=S C\left(I-D D^{*}\right)(S C)^{*}	.
		\end{split}
	\end{equation*}


	Thus $T T^{\#} \leq S S^{\# } $.



	Since $\ker D=\ker A$ and $\overline{\text{ran}}(D)=(\ker B)^{\perp}$, we have


	\begin{equation*}
		\ker D=\ker (TC)=C\ker T\quad\text{and}\quad \overline{\text{ran}}(D)=(\ker (SC))^\perp=(C\ker S)^\perp=C(\ker S)^\perp.
	\end{equation*}

	Thus $$\ker R= \ker (CDC)=\ker (DC)=C\ker D=C\ker(TC)=\ker T, $$ and	
	$$\overline{\text{ran}}(R)=\overline{\text{ran}}(CDC)=(\ker(CD^*C) )^\perp=(\ker(D^*C) )^\perp=C\overline{\text{ran}}(D)=(\ker S)^\perp. $$
	This completes the proof.

Let $C$ be a conjugation. Then	$ S^{\#} S=T^{\#} T$ implies	$ C S^{\#} S C=C T^{\#} T C$. Now set $A=C S^{*}$ and $B=C T^{*}$. Then $A A^{*}=B B^{*}$. By Douglas Theorem,

	$$A=B D^{*},$$ where $D$ is a linear partial isometry with initial Space $\overline{\text{ran}}\left(B^{*}\right)$ and final space $\overline{\text{ran}}\left(A^{*}\right)$.

	This implies

	\begin{equation*}
		\begin{split}
				C S^{*} & =C T^{\#} D^{*} \\
			\quad S^{\#} & =T^{\#} D^{*} \\
			S & =D T.
		\end{split}
	\end{equation*}

	Since $\overline{\text{ran}}\left(B^{*}\right)=\ker(B)^{\perp}=\ker\left(C T^{*}\right)^{\perp}=\ker\left(T^{*}\right)^{\perp}=\overline{\text{ran}}\left(T\right)$ and $\overline{\text{ran}}\left(A^{*}\right)=\overline{\text{ran}}(S).$ The operator $D$ is linear partial isometry with initial space $\overline{\text{ran}}(T)$ and final space $\overline{\text{ran}}(S)$.

Since $A$ is an anti-linear operator and $C$ is a conjugation, the operator $CA$ is bounded linear. Then note that $|CA||CA|=(CA)^*(CA)$ and $|A|=|CA|$. Set $\tilde{A}=(CA)^*$ and $\tilde{B}=|A|$ and then by applying Douglas theorem, we get
	\begin{equation*}
		\begin{split}
			\tilde{A}&=\tilde{B}D\quad\text{which implies}\\
			A&=CD^*|A|\\
			A&=J|A|,
		\end{split}
	\end{equation*}
	where $	J=CD^*$	for some $D\in \mathcal{B}(\mathcal{H})$ with $\ker D=\ker \tilde{A}$ and $\overline{\text{ran}}D=(\ker \tilde{B})^\perp$. Therefore,
	\begin{equation*}
		\ker J=\ker (CD^*)=\ker D^*=(\text{ran}D)^\perp=\ker\tilde{B}=\ker |A|=\ker A.\end{equation*}
	Also, $J$ is anti-linear and isometry on  $\overline{\text{ran}}(|A|)=(\ker J)^\perp.$

Let $T\in \mathcal{B}(\mathcal{H})$ be $C$-normal operator that is, $CT^*TC=TT^*$ equivalently, $C|T|C=|T^*|$. Then by setting $A=CT^*C$ and $B=|T^*|$, we have $AA^*=BB^*$. Now apply Douglas theorem, we get $A=BD^*$ for some $D:\overline{\text{ran}}(B^*)\rightarrow\overline{\text{ran}}(A^*)$ such that $DB^*x=A^*x$, and $Dx=0$ for all $x\in \overline{\text{ran}}(B^*)^\perp=\ker B$. Thus we have
	\begin{equation*}
		\begin{split}
			CT^*C&=|T^*|D^*\\
			T&=CD|T^*|C\\
			T&=CDC|T|.
		\end{split}
	\end{equation*}
	By defininig $J=DC$, we get $T=CJ|T|$. Note that
	\begin{equation*}
		\begin{split}
			\ker J=\ker DC=C\ker D&=C\ker B=	C\ker |T^*|\\&=\ker (|T^*|C)=\ker (C|T|)=\ker |T|=\overline{\text{ran}}(|T|)^\perp,
		\end{split}
	\end{equation*}
	and
	\begin{equation*}
		\begin{split}
			\overline{\text{ran}}(J)=\overline{\text{ran}}(DC)=\overline{\text{ran}}(D)&=\overline{\text{ran}}(CTC)=C\overline{\text{ran}}(T)=C(\ker T^*)^\perp\\&=(\ker |T^*|C)^\perp=(\ker C|T|)^\perp=\overline{\text{ran}}(|T|)
		\end{split}
	\end{equation*}
	Since $\overline{\text{ran}}(B^*)=\overline{\text{ran}}(|T^*|)=C\overline{\text{ran}}(|T|)$, and $\overline{\text{ran}}(A^*)=\overline{\text{ran}}(|T|)$,
	it is evident that $J=DC$ is anti-linear unitary operator supported on $\overline{\text{ran}}(|T|)$.

	Also,
	\begin{equation*}
		|T^*|^2=TT^*=CJ|T||T|J^\#C=CJ|T|J^\#CCJ|T|J^\#C
	\end{equation*}
This implies $|T^*|=CJ|T|J^\#C$ and consequently, $J|T|=|T|J$.

The converse follows trivially.

\label{commute:spectral measure and conju}
		Let $C$ be a conjugation, and $T\in \mathcal{B}(\mathcal{H})$ be $C$-normal. Then we have the following:\begin{enumerate}
			\item\label{normal:C-normal:spectral measure} If $T$ is normal, then the conjugation $C$ commutes with spectral measure of $T^*T$. That is, if $E$ is the projection-valued spectral measure of $T^*T$, then 
			\begin{equation*}
			C E(G)=E(G)C
			\end{equation*}
			for every Borel subset $G$ of $[0,\infty)$. In particular, $C$ reduces the range of $E(G)$.
			\item\label{spectral measure: CT} The anti-linear operator $CT$ commutes with projection-valued spectral measure of $T^*T$.
		\end{enumerate}

{\bf Proof of (\ref{normal:C-normal:spectral measure})}	Since $T$ is $C$-normal as well as normal, we have 
	\begin{equation*}
	CT^*T=TT^*C=T^*TC
	\end{equation*}
	which shows that $C$ commutes with $T^*T$. Then $C$ commutes with $f(T^*T)$ for every $f\in C(\sigma(T^*T))$. Let $G$ be a nonempty open subset of $\sigma(T^*T)$. Let $\{f_n\}\subseteq C(\sigma(T^*T))$ be such that $0\leq f_n\leq \chi_G$ and $f_n\nearrow \chi_G$. Then
	\begin{equation}
	\begin{split}
	\overline{\langle CE(G)g,h\rangle}&=\langle E(G)g,Ch\rangle\\
	&=E_{g,Ch}(G)\\
	&=\lim \int f_n(\lambda)dE_{g,Ch}(\lambda)\\
	&=\lim\langle f_n(T^*T)g,Ch\rangle\\
	&=\lim\langle h,Cf_n(T^*T)g\rangle\\
		&=\lim\langle h,f_n(T^*T)Cg\rangle,
	\end{split}
	\end{equation}
	and it follows that
	\begin{equation}
	\begin{split}
	\langle CE(G)g,h\rangle &=\lim\langle f_n(T^*T)Cg,h\rangle\\
	&=E_{Cg,h}(G)=\langle E(G)Cg,h\rangle.
	\end{split}
	\end{equation}
	This shows that $C$ commutes with spectral measure of $T^*T$.

	{\bf Proof of (\ref{spectral measure: CT}):} Since $T$ is $C$-normal, then we have
	\begin{equation}
	CT(T^*T)=(CTT^*)T=(T^*TC)T=T^*T(CT),
	\end{equation}
	which shows that $CT$ commutes with $T^*T$. Therefore, following the same steps as in (\ref{normal:C-normal:spectral measure}), we get the desired conclusion.

Let $(X, \mu)$ be a measure space. Let $L^2(X,\mu)$ be a space of complex valued functions with conjugation $S_\mu$ given by
	 \begin{equation}\label{conju on L^2}
		S_\mu f(x)=\overline{f(x)}.
	\end{equation}
	 Let $\psi\in L^\infty$ and $M_\psi$ be the multiplication operator on $L^2(X,\mu)$ defined by
	$M_\psi f=\psi f$. Then $M_\psi $ is $S_\mu$-symmetric, and hence $S_\mu$-normal.
	It is well known that from the spectral theory that any normal operator $N\in \mathcal{B}(\mathcal{H})$ is unitary equivalent to the multiplication operator $M_\psi$ that is,
	$M_\psi=VNV^*$, where $V\in \mathcal{B}(\mathcal{H},L^2(X,\mu))$ is a unitary. Let $\tilde{C}$ be a conjugation in $\mathcal{H}$ such that $(V\tilde{C}V^*)f(x)=S_\mu f(x)$. Then $N$ is $\tilde{C}$-normal.	More precisely, if $N$ is a normal operator, then $N$ is $\tilde{C}$-normal, where the conjugation $\tilde{C}$ on $\mathcal{H}$ is related to the conjugation $S_\mu$ on $L^2(X,\mu)$ by the relation \begin{equation}\label{second relation}
	\tilde{C}=V^*S_\mu V.
	\end{equation}

\label{Commute conju and T^*T}
Let $C$ be a conjugation on $\mathcal{H}$, and suppose $T$ is $C$-normal. If $T$ is normal then 
\begin{equation}
C=U^*M_\varphi V\tilde{C} V^*U,
\end{equation}
where $U,V:\mathcal{H}\rightarrow L^2(\mu)$ are unitaries, $M_\varphi$ is the multiplication operator on $L^2(\mu)$ and $\varphi\in L^\infty(\mu)$.

Since the linear operator $T^*T$ is positive, by spectral theorem for normal operator, there is a unitary operator $U:\mathcal{H}\rightarrow L^2(\mu)$ such that $T^*T=U^*M_xU$, where $M_x$ is the multiplication operator induced by the real variable $x$. Therefore, $E_{T^*T}=U^*E_{M_x}U$, where $E_{T^*T}$ and $E_{M_x}$are the projection-valued spectral measures corresponding to $T^*T$ and $M_x$, respectively. Since $T$ is $C$-normal and normal, by (\ref{normal:C-normal:spectral measure}) of \cref{commute:spectral measure and conju}, we have
	\begin{equation}\label{antilinear commute spec measure}
	\begin{split}
	CU^*E_{M_x}U&=U^*E_{M_x}UC,\,\text{or}\\
	UCU^*E_{M_x} &=E_{M_x}UCU^*.
	\end{split}
	\end{equation}
	Observe that $S_\mu M_x=M_xS_\mu$, as well as $S_\mu E_{M_x}=E_{M_x}S_\mu$. Therefore, by \cref{antilinear commute spec measure}, we have
	\begin{equation*}
	UCU^*S_\mu E_{M_x} =E_{M_x}UCU^*S_\mu,
	\end{equation*}
	and this implies the linear operator $UCU^*S_\mu$ belongs to the commutant of $M_x$. 

Hence there exists an essentially bounded measurable function $\varphi$ such that $UCU^*S_\mu=M_\varphi$, where $M_\varphi$ is the multiplication operator on $L^2(\mu)$ induced by $\varphi$ with $|\varphi|=1 $ $\mu$-a.e. It follows that 
	\begin{equation}\label{first relation}
	C=U^*M_\varphi S_\mu U.
	\end{equation}
	Hence by using \cref{second relation}, we obtain the desired conclusion.

Let $C$ be a conjugation on $\mathcal{H}$. In (\ref{spectral measure: CT}) of \cref{commute:spectral measure and conju}, we have seen that if $T$ is $C$-normal, then the anti-linear operator $CT$ commutes with the projection-valued spectral measure $E_{T^*T}$ associated to the positive operator $T^*T$. By continuing, in the similar fashion as earlier, we have
\begin{equation}
\begin{split}
CTE_{T^*T}(G)&=E_{T^*T}(G)CT,\text{or}\\
CTU^*E_{M_x}U&=U^*E_{M_x}U CT,\,\text{that is,}\\
UCTU^*S_\mu E_{M_x}&=E_{M_x}U CT U^*S_\mu.
\end{split}
\end{equation}
Hence the linear operator $UCTU^*S_\mu$ is a commutant of $M_x$. Therefore, there exists $\varphi\in L^\infty(\mu)$ such that $UCTU^*S_\mu=M_\varphi$, which implies that $T=CU^*M_\varphi S_\mu U$.

\begin{enumerate}
		\item The anti-unitary operator $J_{n}=U_{n} S_{\mu_{n}}^{(n)}$, where $U_{n}$ unitary operator matrix is conjugation if and only if $U_{n}$ is symmetric unitary operator matrix.
		\item The anti-unitary operator $J_{n}=U_{n} S_{\mu_{n}}^{(n)}$, where $U_{n}$ unitary operator matrix is anti-conjugation if and only if $U_{n}$ is skew-symmetric unitary operator matrix.
	\end{enumerate}

\label{cart decomp C-normal}
	Let $C$ be a conjugation on $\mathcal{H}$, and $T\in \mathcal{B}(\mathcal{H})$ be such that $T=A+iB$, where $A$ is $C$-symmetric and $B$ is $C$-skew-symmetric. Then the following are equivalent:
	\begin{enumerate}
		\item\label{C-normal} $T$ is $C$-normal.
		\item\label{parallelogram law} $\left\|Tx\right\|^2=\left\|Ax\right\|^2+\left\|Bx\right\|^2$ for all $x\in \mathcal{H}$.
		\item\label{adj_commute-1} $A^*B=B^*A$.
			\item\label{adj_commute-2} $AB^*=BA^*$.
	\end{enumerate}
In this case, $T^*T=A^*A+B^*B$ and $TT^*=AA^*+BB^*$ with $(A^*A)(B^*B)=(B^*B)(A^*A)$, and $\max \{\|A\|^2,\|B\|^2  \}\leq\|T\|^2\leq \|A\|^2+\|B\|^2$.

Let $C$ be a conjugation, and $T=A+iB$, where $A$ is $C$-symmetric and $B$ is $C$-skew-symmetric (cf. \cite[Theorem 2.3]{RSV_Cart}). Therefore, for every $x\in \mathcal{H}$
	\begin{equation}
	\begin{split}
	\left\|Tx\right\|^2=\left\|(A+iB)x\right\|^2=\left\|Ax\right\|^2+\left\|Bx\right\|^2-2\Re (i\langle Ax,Bx\rangle),
	\end{split}
	\end{equation}
	and 
	\begin{equation*}
	\begin{split}
	\left\|T^*x\right\|^2=\left\|(A^*-iB^*)x\right\|^2=\left\|A^*x\right\|^2+\left\|B^*x\right\|^2+2\Re (i\langle A^*x,B^*x\rangle).
	\end{split}
	\end{equation*}
	Since $T$ is $C$-normal, we have $\left\|Tx\right\|=\left\|T^*Cx\right\|$, and this implies 
	\begin{equation}
	\begin{split}
	\left\|Ax\right\|^2+\left\|Bx\right\|^2-2\Re (i\langle Ax,Bx\rangle)&=\left\|A^*Cx\right\|^2+\left\|B^*Cx\right\|^2+2\Re (i\langle A^*Cx,B^*Cx\rangle)\\
	&=\left\|Ax\right\|^2+\left\|Bx\right\|^2-2\Re (i\langle CAx,CBx\rangle)\\
	&=\left\|Ax\right\|^2+\left\|Bx\right\|^2-2\Re (i\langle Bx,Ax\rangle)\\
	&=\left\|Ax\right\|^2+\left\|Bx\right\|^2+2\Re (i\langle Ax,Bx\rangle)\quad(\Re z=\Re\bar{z}).
	\end{split}
	\end{equation}
	Thus for every $x\in \mathcal{H}$, we have $T$ is $C$-normal if and only if $\left\|Tx\right\|=\left\|T^*Cx\right\|$ if and only if $\Re (i\langle Ax,Bx\rangle)=0$ if and only if  $\left\|Tx\right\|^2=\left\|Ax\right\|^2+\left\|Bx\right\|^2$. 

	Now observe that $\Re (i\langle Ax,Bx\rangle)=0$ if and only if $\langle Ax,Bx\rangle\in \mathbb{R}$ for all $x\in \mathcal{H}$ if and only if $(B^*A)^*=B^*A$, that is, $A^*B=B^*A$. Since $A$ is $C$-symmetric and $B$ is $C$-skew-symmetric, we have
	$A^*B=B^*A\iff CA^*B=CB^*A \iff ACB=-BCA \iff -AB^*C=-BA^*C\iff AB^*=BA^*$. This completes the proof.

\label{cwshift}
	Let $C$ be the conjugation on $\mathbb{C}^n$ defined by 
	\begin{align}\label{standconju}
		C(z_1,z_2,\dots, z_n)=(\widebar{z_n},\widebar{z_{n-1}},\dots, \widebar{z_2},\widebar{z_1}).
	\end{align} Then
	\begin{align}\label{wshft}
		T=\displaystyle\sum_{j=1}^{n-1}\lambda_j e_j\otimes e_{j+1}
	\end{align} is $C$-normal if and only if $|\lambda_j|=|\lambda_{n-j}|$ for $j=1,2,\dots, n-1$.

To prove this, we use the Cartesian decomposition of $C$-normal operators (See Theorem \ref{cart decomp C-normal}). We write $T=A+iB$, where
	\begin{align*}
		A=\frac{T+CT^*C}{2}=\frac{1}{2}\displaystyle\sum_{j=1}^{n-1}(\lambda_{n-j}+\lambda_j)e_j\otimes e_{j+1}
	\end{align*}
	and 
	\begin{align*}
		B=\frac{T-CT^*C}{2i}=\frac{1}{2i}\displaystyle\sum_{j=1}^{n-1}(\lambda_j-\lambda_{n-j})e_j\otimes e_{j+1}.
	\end{align*} 
	Also note that
	$$AB^*=\displaystyle\sum_{j=1}^{n-1}\frac{(\lambda_{n-j}+\lambda_j)(\bar{\lambda_{n-j}}-\bar{\lambda_j})}{4i}e_j\otimes e_j$$ and
	$$BA^*=\displaystyle\sum_{j=1}^{n-1}\frac{(\lambda_j-\lambda_{n-j})(\bar{\lambda_{n-j}}+\bar{\lambda_j})}{4i}e_j\otimes e_j.$$
	The condition $AB^*=BA^*$ implies
	\begin{align*}
		(\lambda_{n-j}+\lambda_j)(\bar{\lambda_{n-j}}-\bar{\lambda_j})=(\lambda_j-\lambda_{n-j})(\bar{\lambda_{n-j}}+\bar{\lambda_j})
	\end{align*} and this implies $|\lambda_{n-j}|=|\lambda_j|$ for all $1\leq j\leq n-1$. Hence the conclusion follows.

Let $C$ be  conjugation defined by  $Cf(t)=\overline{f(1-t)}$ for all $t\in [0,1]$ and consider the multiplication operator $M_\varphi f=\varphi f$ for all $f\in L^2[0,1]$. Then $M_\varphi\in \mathcal{B}(L^2[0,1])$ for $\varphi\in L^\infty$. Then \begin{equation*}
		A=\frac{1}{2}M_{\psi_{1}}\quad\text{and}\quad 	B=\frac{1}{2i}M_{\psi_{2}},
	\end{equation*}
	where $\psi_1(t)=\varphi(t)+\varphi(1-t)$ and $\psi_2(t)=\varphi(t)-\varphi(1-t)$. Therefore, by Theorem \ref{cart decomp C-normal}, $M_\varphi$ is $C$-normal if and only if $A^*B=B^*A$ that is $\bar{\psi_{1}}\psi_2=\bar{\psi_{2}}\psi_1$ which implies $|\varphi(1-t)|^2=|\varphi(t)|^2$.

Since $T$ is a compact $C$-normal operator, it follows from \cref{cart decomp C-normal} that $T=A+iB$, where $A$ is $C$-symmetric and $B$ is $C$-skew-symmetric such that $A^*B=B^*A$ and $|T|=\sqrt{|A|^2+|B|^2}$ with $|A||B|=|B||A|$. Thus we have 
\begin{equation}
\frac{1}{\sqrt{2}}(||A|+|B||)\leq \sqrt{|A|^2+|B|^2}=|T|\leq |A|+|B|.
\end{equation}
Hence, by using Weyl's monotonicity principle the conclusion follows.

It is well known that if $A,B$ are compact operators, then
	\begin{equation}\label{Bhati-Kitta ineq}
	s_j(AB^*+BA^*)\leq s_j((A^*A+B^*B)\oplus (AA^*+BB^*)),
	\end{equation}
	for $j=1,2,\dots$ (cf. \cite{Bhatia:Kittaneh}).
	Therefore, if $T\in \mathcal{B}(\mathcal{H})$ is compact $C$-normal with the Cartesian decomposition $T=A+iB$, by using \cref{cart decomp C-normal}, we have $T^*T=A^*A+B^*B$ and $TT^*=AA^*+BB^*$, and hence by \cref{Bhati-Kitta ineq}, we have $2s_j(BA^*)=2s_j(AB^*)\leq s_j((T^*T)\oplus(TT^*) )$ for $j=1,2,\dots$.
